#!/usr/bin/env bash
# Generate a CycloneDX SBOM for one runtime identifier, from the real NuGet
# restore graph rather than a hand-kept list.
#
# The CycloneDX .NET tool runs `dotnet restore` for the requested RID and then
# reads obj/project.assets.json — the same file MSBuild itself resolves against
# — so what lands in the SBOM is what the build actually linked, transitives
# included. `-rs` walks the ProjectReferences (Dmart.Models,
# Dmart.QueryGrammar) that compile into the AOT binary.
#
# What this covers, and what it does not: the SBOM lists NuGet package
# dependencies. It does NOT list the .NET SDK, ILCompiler, clang, or the
# system libraries the AOT binary links against (glibc, openssl, zlib). Those
# are build-toolchain and platform facts, recorded in the SLSA provenance
# instead. Say so when someone asks whether the SBOM is "complete".
#
# Usage:
#   dist/sbom.sh --rid linux-x64 --version 1.2.6 --out dist/out
#   dist/sbom.sh --rid linux-musl-arm64 --version 1.2.6 --out dist/out \
#                --filename dmart-1.2.6-linux-musl-arm64.cdx.json
set -euo pipefail

# Pinned deliberately. A supply-chain artifact generated by a floating tool
# version is a supply-chain artifact you cannot reason about.
CYCLONEDX_VERSION="6.2.0"
# CycloneDX 6.x defaults to spec 1.7. actions/attest-sbom validates the
# document before wrapping it in a predicate, and 1.6 is the newest version
# its validator is known to accept. Emitting 1.6 costs nothing here.
SPEC_VERSION="1.6"

RID=""
VERSION=""
OUT=""
FILENAME=""
FRONTEND=""

while [ $# -gt 0 ]; do
	case "$1" in
		--rid)       RID="$2"; shift 2 ;;
		--version)   VERSION="$2"; shift 2 ;;
		--out)       OUT="$2"; shift 2 ;;
		--filename)  FILENAME="$2"; shift 2 ;;
		--frontend)  FRONTEND="$2"; shift 2 ;;
		-h|--help)
			awk 'NR>1 && /^#/ {sub(/^# ?/, ""); print; next} NR>1 {exit}' "$0"
			exit 0 ;;
		*) echo "sbom.sh: unknown argument: $1 (try --help)" >&2; exit 2 ;;
	esac
done

[ -n "$RID" ]     || { echo "sbom.sh: --rid is required" >&2; exit 2; }
[ -n "$VERSION" ] || { echo "sbom.sh: --version is required" >&2; exit 2; }
[ -n "$OUT" ]     || { echo "sbom.sh: --out is required" >&2; exit 2; }
[ -n "$FILENAME" ] || FILENAME="dmart-${VERSION}-${RID}.cdx.json"

cd "$(dirname "$0")/.."

command -v dotnet >/dev/null 2>&1 || {
	echo "sbom.sh: no dotnet on PATH — the SBOM is generated from a restore," >&2
	echo "         so the SDK has to be here even when the binary was built" >&2
	echo "         inside a container." >&2
	exit 1
}

# --tool-path rather than --global: no dependency on ~/.dotnet/tools being on
# PATH, and nothing is left behind on a self-hosted runner that a later job
# could pick up by accident.
TOOLDIR="${SBOM_TOOL_DIR:-${TMPDIR:-/tmp}/cyclonedx-${CYCLONEDX_VERSION}}"
if [ ! -x "$TOOLDIR/dotnet-CycloneDX" ]; then
	echo "== installing CycloneDX $CYCLONEDX_VERSION into $TOOLDIR"
	dotnet tool install CycloneDX --version "$CYCLONEDX_VERSION" --tool-path "$TOOLDIR"
fi

mkdir -p "$OUT"


echo "== CycloneDX SBOM: rid=$RID version=$VERSION -> $OUT/$FILENAME"
# -rs  recurse into ProjectReferences (Dmart.Models, Dmart.QueryGrammar)
# -t   exclude test projects
# -ed  exclude packages marked as development dependencies
# -dct 600000 — the restore is a cold one on a fresh runner; the 300s default
#      has to cover a full package download over whatever the network is doing.
"$TOOLDIR/dotnet-CycloneDX" dmart.csproj \
	-rt "$RID" \
	-tfm net10.0 \
	-rs -t -ed \
	-F Json \
	-spv "$SPEC_VERSION" \
	-o "$OUT" \
	-fn "$FILENAME" \
	-sn dmart \
	-sv "$VERSION" \
	-dct 600000

# An SBOM that silently came out empty is worse than no SBOM: it verifies
# fine and tells the reader the binary has no dependencies.
COMPONENTS=$(grep -c '"purl"' "$OUT/$FILENAME" || true)
if [ "${COMPONENTS:-0}" -lt 5 ]; then
	echo "sbom.sh: $OUT/$FILENAME lists $COMPONENTS components — that is not a" >&2
	echo "         real restore graph for this project. Refusing to publish it." >&2
	exit 1
fi
echo "== $FILENAME: $COMPONENTS components"

# The runtime packs are NOT in the restore graph the CycloneDX tool reads: the
# SDK injects them through FrameworkReference, so project.assets.json never
# names them. But this project publishes self-contained with PublishAot, which
# means Microsoft.NETCore.App.Runtime.<rid> and
# Microsoft.AspNetCore.App.Runtime.<rid> are compiled INTO the binary and ship
# inside it.
#
# An SBOM that omits them understates the largest thing being deployed — and,
# because a self-contained runtime cannot be patched independently of the
# binary, the component a consumer most needs to see. v1.2.7's SBOM listed 467
# components and neither of these, while the binary it described carried
# runtime 10.0.10 and three CVEs.
#
# Ask MSBuild rather than assuming the version follows the SDK:
# ProcessFrameworkReferences resolves the exact packs for this RID, and needs
# no restore to do it.
echo "== resolving runtime packs for $RID"
RPJSON="$(mktemp)"
dotnet msbuild dmart.csproj \
	-p:RuntimeIdentifier="$RID" -p:SelfContained=true \
	-t:ProcessFrameworkReferences -getItem:RuntimePack -nologo > "$RPJSON" || {
	echo "sbom.sh: could not resolve the runtime packs for $RID. Rather than" >&2
	echo "         publish an SBOM that silently omits the runtime shipping" >&2
	echo "         inside the binary, this is a failure." >&2
	exit 1
}
python3 - "$OUT/$FILENAME" "$RPJSON" <<'RUNTIMEPACKS'
import json, sys

doc_path, packs_path = sys.argv[1], sys.argv[2]
doc = json.load(open(doc_path))
packs = json.load(open(packs_path)).get("Items", {}).get("RuntimePack", [])

# No packs means the resolution silently did nothing, which would produce
# exactly the incomplete SBOM this block exists to prevent.
if not packs:
    sys.exit("sbom.sh: MSBuild resolved no runtime packs; refusing to write an "
             "SBOM that omits the runtime.")

seen = {c.get("purl") for c in doc.get("components", [])}
added = []
for p in packs:
    name, ver = p.get("NuGetPackageId"), p.get("NuGetPackageVersion")
    if not name or not ver:
        sys.exit("sbom.sh: runtime pack with no id/version: %r" % (p,))
    purl = "pkg:nuget/%s@%s" % (name, ver)
    if purl in seen:
        continue
    doc.setdefault("components", []).append({
        "type": "library",
        "bom-ref": purl,
        "name": name,
        "version": ver,
        "purl": purl,
        "scope": "required",
        "description": ".NET runtime pack compiled into the self-contained AOT "
                       "binary; it ships inside the executable and cannot be "
                       "patched separately from it.",
    })
    seen.add(purl)
    added.append("%s %s" % (name, ver))

json.dump(doc, open(doc_path, "w"), indent=2)
print("== added %d runtime pack component(s): %s" % (len(added), "; ".join(added)))
RUNTIMEPACKS
rm -f "$RPJSON"
COMPONENTS=$(grep -c '"purl"' "$OUT/$FILENAME" || true)
echo "== $FILENAME: $COMPONENTS components (server + runtime)"

# Licences for the .NET side, read from each package's .nuspec in the NuGet
# cache. The CycloneDX tool leaves some components with none at all, and an
# unlicensed component is not a cosmetic gap: it is indistinguishable from a
# permissively licensed one, so a term that needs a decision reads as
# uninteresting. The frontend half already does this (dist/frontend-sbom.sh);
# this is the same job for the packages that ship inside the binary.
NUGET_ROOT="${NUGET_PACKAGES:-$HOME/.nuget/packages}"
NUGET_ROOT="$NUGET_ROOT" python3 - "$OUT/$FILENAME" <<'LICENCES'
import json, os, re, sys, glob

doc_path = sys.argv[1]
doc = json.load(open(doc_path))
root = os.environ["NUGET_ROOT"]

# The identifiers CycloneDX accepts in `license.id`. That field is an
# enumeration, and a value outside it fails the schema validation
# actions/attest-sbom runs before signing, so anything unrecognised goes to
# `license.name` instead — lossier, but always valid.
SPDX_IDS = frozenset("""
0BSD Apache-2.0 BSD-2-Clause BSD-3-Clause MIT MIT-0 MS-PL ISC MPL-2.0
PostgreSQL Unlicense Zlib LGPL-2.1-only LGPL-2.1-or-later LGPL-3.0-only
LGPL-3.0-or-later GPL-2.0-only GPL-3.0-only AGPL-3.0-only Apache-1.1 BSL-1.0
CC0-1.0 CC-BY-4.0
""".split())

LICENSE_EL = re.compile(r'<license\s+type="(expression|file)"\s*>([^<]+)</license>')
LICENSE_URL = re.compile(r'<licenseUrl>([^<]+)</licenseUrl>')

def nuspec_for(name, version):
    # The cache lower-cases both directory levels.
    pat = os.path.join(root, name.lower(), version.lower(), "*.nuspec")
    hits = glob.glob(pat)
    return hits[0] if hits else None

def licence_of(name, version):
    """(cyclonedx entry, kind, note) or (None, None, None)."""
    path = nuspec_for(name, version)
    if not path:
        return None, None, None
    try:
        text = open(path, encoding="utf-8", errors="replace").read()
    except Exception:
        return None, None, None

    m = LICENSE_EL.search(text)
    if m:
        kind, value = m.group(1), m.group(2).strip()
        if kind == "expression":
            if value in SPDX_IDS:
                return {"license": {"id": value}}, "id", None
            return {"expression": value}, "expression", None
        # type="file": the package ships its own terms rather than naming an
        # SPDX licence. That is exactly the case worth a human reading it.
        return ({"license": {"name": "see %s in the package" % value}},
                "file", value)

    m = LICENSE_URL.search(text)
    url = m.group(1).strip() if m else ""
    # Microsoft deprecated licenseUrl in favour of <license>; the placeholder
    # carries no information, so treat it as absent rather than record it.
    if url and "deprecateLicenseUrl" not in url:
        return {"license": {"name": "see %s" % url, "url": url}}, "url", None
    return None, None, None

filled, review, missing = 0, [], []
for c in doc.get("components", []):
    if c.get("licenses"):
        continue
    name, ver = c.get("name"), c.get("version")
    if not name or not ver:
        continue
    entry, kind, note = licence_of(name, ver)
    if entry is None:
        missing.append("%s@%s" % (name, ver))
        continue
    c["licenses"] = [entry]
    filled += 1
    if kind in ("file", "url"):
        review.append("%s@%s  %s" % (name, ver, note or "licenceUrl only"))

json.dump(doc, open(doc_path, "w"), indent=2)

total = len(doc.get("components", []))
have = sum(1 for c in doc.get("components", []) if c.get("licenses"))
print("== licences: %d/%d components (%d filled from .nuspec)" % (have, total, filled))
if review:
    # Printed, never summarised to a count: a package shipping its own terms is
    # the one licence outcome that needs a person, and the count alone would not
    # say which package.
    print("== %d component(s) ship their own licence text and need review:" % len(review))
    for r in sorted(review):
        print("     " + r)
if missing:
    print("== %d component(s) still declare no licence:" % len(missing))
    for m in sorted(missing)[:20]:
        print("     " + m)
LICENCES

# Merge the embedded Svelte frontends (cxb, catalog). dmart compiles their built
# SPAs into the AOT binary via ManifestEmbeddedFileProvider, so their npm
# dependencies ship inside /usr/bin/dmart; a .NET-only SBOM understates what is
# deployed. The frontend document is produced once by dist/frontend-sbom.sh.
if [ -n "$FRONTEND" ]; then
	[ -r "$FRONTEND" ] || { echo "sbom.sh: --frontend $FRONTEND not readable" >&2; exit 1; }
	python3 - "$OUT/$FILENAME" "$FRONTEND" <<'PY'
import json, sys
base = json.load(open(sys.argv[1]))
front = json.load(open(sys.argv[2]))
seen = {c.get("purl") or (c.get("name"), c.get("version")) for c in base.get("components", [])}
added = 0
for c in front.get("components", []):
    k = c.get("purl") or (c.get("name"), c.get("version"))
    if k not in seen:
        base.setdefault("components", []).append(c)
        seen.add(k)
        added += 1
# A merged dependency graph would reference bom-refs from the other document
# that no longer resolve; Dependency-Track rejects a dangling ref, so drop it.
base.pop("dependencies", None)
json.dump(base, open(sys.argv[1], "w"), indent=2)
print("== merged %d frontend components into %s" % (added, sys.argv[1].split("/")[-1]))
PY
	COMPONENTS=$(grep -c '"purl"' "$OUT/$FILENAME" || true)
	echo "== $FILENAME: $COMPONENTS components (server + frontends)"
fi
